package com.lmspilot.configuration.api;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.Cipher;import javax.crypto.spec.*;import java.nio.ByteBuffer;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.Arrays;@Service public class ConfigurationSecretCipher{private final SecureRandom random=new SecureRandom();private final SecretKeySpec key;public ConfigurationSecretCipher(@Value("${configuration.secret-key}")String secret)throws Exception{key=new SecretKeySpec(MessageDigest.getInstance("SHA-256").digest(secret.getBytes(StandardCharsets.UTF_8)),"AES");}public byte[]encrypt(String value){try{byte[]nonce=new byte[12];random.nextBytes(nonce);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,nonce));byte[]e=c.doFinal(value.getBytes(StandardCharsets.UTF_8));return ByteBuffer.allocate(nonce.length+e.length).put(nonce).put(e).array();}catch(Exception x){throw new IllegalStateException(x);}}public String decrypt(byte[]v){if(v==null||v.length<=12)throw new IllegalArgumentException("Encrypted secret is invalid");try{byte[]n=Arrays.copyOfRange(v,0,12),e=Arrays.copyOfRange(v,12,v.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,n));return new String(c.doFinal(e),StandardCharsets.UTF_8);}catch(Exception x){throw new IllegalStateException(x);}}}
